def canDistribute(nums: list[int], quantity: list[int]) -> bool:
    from collections import Counter
    counts = sorted(Counter(nums).values(), reverse=True)
    m = len(quantity)
    quantity.sort(reverse=True)
    def backtrack(cust_idx):
        if cust_idx == m: return True
        q = quantity[cust_idx]
        for i in range(len(counts)):
            if counts[i] >= q:
                counts[i] -= q
                if backtrack(cust_idx + 1): return True
                counts[i] += q
            if counts[i] == 0: break
        return False
    return backtrack(0)

